// Tabular Q-learning.
// State = (which bin the z-score of the price relative to its moving average falls in, current position); action = short / flat / long.
// Reward = this step's log return, net of the cost of changing position.

function stateOf(s, p, prev) {                  // prev ∈ {-1, 0, 1}
  var z = s.z(p.n);
  if (!(z === z)) return -1;
  var b = Math.floor((z + 2.5) / 5 * p.bins);
  b = Math.max(0, Math.min(p.bins - 1, b));
  return b * 3 + (prev + 1);
}
function best(Q, k) {                           // the highest-value action in state k (0, 1, 2)
  var a = 1;                                    // ties favor flat
  if (Q[k * 3] > Q[k * 3 + a]) a = 0;
  if (Q[k * 3 + 2] > Q[k * 3 + a]) a = 2;
  return a;
}

